Definition pbl_saved (regs : bvmap 5 word) (fr : bvmap 5 word) : list cell :=
  [(104%Z, 8%nat, u (getr regs 1)); (96%Z, 8%nat, u (getr regs 8)); (88%Z, 8%nat, u (getr regs 9)); (80%Z, 8%nat, u (getr regs 18));
