(* [comment removed for export] *)
Lemma ocomp_keep : forall C Ar A A' m m' r dr w h, ocomp C Ar A m r dr w h ->
  (forall x : word, live A (Z_to_bv 64 r) = Some 64%Z -> (r + 64 <= alloc_top (c_vm C))%Z -> (4096 <= r)%Z -> (r <= u x < r + 64)%Z -> m' x = m x) ->
